INSERT INTO `notice` VALUES (1,'Semester Examination Notice','All students are informed that the semester examination schedule will be published soon. Please check the college notice board regularly.','High'),(2,'Fee Payment Notice','All students are requested to complete their semester fee payment before the last date.','High'),(3,'College Holiday Notice','The college will remain closed on the occasion of the upcoming public holiday.','Medium'),(4,'Internal Assessment Notice','Students are informed that internal assessments will be conducted according to the department schedule.','High'),(5,'Library Book Return Notice','All students must return borrowed library books before the due date to avoid late fees.','Medium'),(6,'Admission Notice','Applications are invited from eligible candidates for admission to various undergraduate courses.','High'),(7,'Practical Examination Notice','Practical examinations will be conducted in the respective department laboratories. Students must bring their practical records.','High'),(8,'Attendance Notice','All students are advised to maintain the minimum required attendance percentage.','High'),(9,'Cultural Programme Notice','The college is going to organize an annual cultural programme. Interested students can register their names.','Low'),(10,'Sports Event Notice','Students interested in participating in the annual sports competition are requested to contact the sports department.','Low'),(11,'Project Submission Notice','BCA students are informed to submit their semester project reports within the specified deadline.','High'),(12,'Seminar Notice','A technical seminar will be organized by the college. All interested students are welcome to participate.','Medium'),(13,'Scholarship Notice','Eligible students are requested to apply for available government scholarships within the application deadline.','High'),(14,'Parent Teacher Meeting','A parent teacher meeting will be organized to discuss students academic performance and progress.','Medium'),(15,'Computer Lab Notice','Students must follow laboratory rules and maintain discipline while using college computer facilities.','Medium'),(16,'Holiday Due to Weather','The college may remain closed due to severe weather conditions. Students should follow official announcements.','High'),(17,'Identity Card Notice','All students must carry their valid college identity cards inside the campus.','Medium'),(18,'Placement Training Notice','A placement training programme will be organized to help students prepare for job interviews.','Medium'),(19,'Document Verification Notice','Students are requested to submit their required academic documents to the college office for verification.','High'),(20,'New Academic Session Notice','Students are informed that the new academic session will begin according to the official academic calendar.','Medium');
/*!40000 ALTER TABLE `notice` ENABLE KEYS */;
